const markScheduledMessageFailed = `-- name: MarkScheduledMessageFailed :exec
UPDATE message
SET status = ?,
    last_error = ?,
    scheduled_attempts = scheduled_attempts + 1,
    locked_at = NULL,
    lock_owner = NULL,
    updated_at = NOW(3)
WHERE id = ?
`

type MarkScheduledMessageFailedParams struct {
	Status    string
	LastError sql.NullString
	ID        string
}

// Records a delivery failure: bumps the attempt counter, releases the worker claim, and sets the new
// status ('scheduled' to retry next tick, or a terminal 'failed'/'canceled').
func (q *Queries) MarkScheduledMessageFailed(ctx context.Context, arg MarkScheduledMessageFailedParams) error {
	_, err := q.db.ExecContext(ctx, markScheduledMessageFailed, arg.Status, arg.LastError, arg.ID)
	return err
}

const promoteDraftMessage = `-- name: PromoteDraftMessage :execrows
UPDATE message
SET status = 'sent',
    sequence = ?,
    visibility = 'external',
    kind = ?,
    approved_by_account_user_id = ?,
    preview = ?,
    updated_at = NOW(3)
WHERE id = ? AND account_id = ? AND status = 'draft'
`

type PromoteDraftMessageParams struct {
	Sequence                sql.NullInt64
	Kind                    string
	ApprovedByAccountUserID sql.NullString
	Preview                 sql.NullString
	ID                      string
	AccountID               string
}

// Approve-and-send: promotes a draft to a sent, customer-visible timeline message IN PLACE. Assigns the
// locked sequence, flips visibility to 'external', and records the approver. The customer-facing
// "Customer Service" branding is applied at read time, not persisted. Guarded on status='draft'
// (compare-and-set) so a concurrent double-approve sends only once.
func (q *Queries) PromoteDraftMessage(ctx context.Context, arg PromoteDraftMessageParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, promoteDraftMessage,
		arg.Sequence,
		arg.Kind,
		arg.ApprovedByAccountUserID,
		arg.Preview,
		arg.ID,
		arg.AccountID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const promoteScheduledMessage = `-- name: PromoteScheduledMessage :execrows
UPDATE message
SET status = 'sent', sequence = ?, locked_at = NULL, lock_owner = NULL, updated_at = NOW(3)
WHERE id = ? AND status = 'scheduled'
`

type PromoteScheduledMessageParams struct {
	Sequence sql.NullInt64
	ID       string
}

// Promotes a claimed scheduled message to a sent timeline message IN PLACE: assigns the locked sequence
// and flips status to 'sent'. Guarded on status='scheduled' (compare-and-set) — the single-delivery
// idempotency guard; rows-affected=0 means a prior tick already delivered it.
func (q *Queries) PromoteScheduledMessage(ctx context.Context, arg PromoteScheduledMessageParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, promoteScheduledMessage, arg.Sequence, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const setDraftMessageStatus = `-- name: SetDraftMessageStatus :execrows
UPDATE message
SET status = ?, updated_at = NOW(3)
WHERE id = ? AND account_id = ? AND status = 'draft'
`

type SetDraftMessageStatusParams struct {
	Status    string
	ID        string
	AccountID string
}

// Transitions an open draft (draft->rejected). Guarded on status='draft' so only an open draft can
// transition; the rows-affected count tells the caller whether the transition applied.
func (q *Queries) SetDraftMessageStatus(ctx context.Context, arg SetDraftMessageStatusParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, setDraftMessageStatus, arg.Status, arg.ID, arg.AccountID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const setMessageStreamingBody = `-- name: SetMessageStreamingBody :execrows
UPDATE message
SET body = ?, preview = ?, streaming_state = ?, updated_at = NOW(3)
WHERE id = ? AND account_id = ? AND streaming_state = 'streaming'
`

type SetMessageStreamingBodyParams struct {
	Body           sql.NullString
	Preview        sql.NullString
	StreamingState string
	ID             string
	AccountID      string
}

// Streams a partial or final body into an in-flight agent reply, optionally flipping streaming_state to
// 'complete'. Deliberately does NOT touch edited_at (streaming is not a human edit). Guarded on the row
// still being 'streaming' so a stale/reordered patch can't clobber an already-completed or deleted
// message — the rows-affected count lets the caller skip the realtime push when the update no-ops.
func (q *Queries) SetMessageStreamingBody(ctx context.Context, arg SetMessageStreamingBodyParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, setMessageStreamingBody,
		arg.Body,
		arg.Preview,
		arg.StreamingState,
		arg.ID,
		arg.AccountID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

